contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        // fund c so it holds at least `amount`
        c.sendTo(address(this), 1); if (__ESBMC_reverted()) return; // cannot fund this way; instead assert on send after checking balance
        // C's balance may be less than amount; choose to send min-able amount only if enough
        uint balC = address(c).balance;
        require(balC >= amount);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        c.sendTo(address(this), amount); if (__ESBMC_reverted()) return;
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        assert(afterC == beforeC - amount && afterThis == beforeThis + amount);
    }
    receive() external payable {}
}

