// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.sendTo(address(this), 1) {} catch { return; }
        uint balC = address(c).balance;
        vm.assume(balC >= amount);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        try c.sendTo(address(this), amount) {} catch { return; }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        assertTrue(afterC == beforeC - amount && afterThis == beforeThis + amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
